// assets/js/fs_compat.js -- compatibility shim generated by assistant
(function(){
  // If assets/js/auth.js exists as module, try to import dynamically (best-effort)
  try {
    // define globals from auth if available
    if (!window.getToken) {
      window.getToken = function(){ try { return localStorage.getItem('fs_token') || sessionStorage.getItem('fs_token') || ''; } catch(e){ return ''; } };
    }
    if (!window.getCurrentUserId) {
      window.getCurrentUserId = function(){
        try {
          const id = localStorage.getItem('fs_user_id');
          if (id) return String(id);
          const token = window.getToken();
          if (!token) return null;
          const parts = token.split('.');
          if (parts.length>1) {
            const payload = JSON.parse(atob(parts[1].replace(/-/g,'+').replace(/_/g,'/')));
            return payload?.sub || payload?.userId || payload?.id || null;
          }
          return null;
        } catch(e) { return null; }
      };
    }
    if (!window.apiFetch) {
      window.apiFetch = async function(path, opts){
        const API = window.FS_API || 'http://localhost:9090';
        const token = window.getToken();
        const headers = Object.assign({}, opts && opts.headers ? opts.headers : {});
        if (token) headers['Authorization'] = 'Bearer ' + token;
        headers['Content-Type'] = headers['Content-Type'] || 'application/json';
        const res = await fetch((API + path).replace(/([^:]\/\/)\/+/g, "$1"), Object.assign({}, opts, { headers: headers, credentials: 'include' }));
        if (res.status === 401) {
          try { localStorage.removeItem('fs_token'); localStorage.removeItem('fs_user_id'); } catch(e){}
          window.dispatchEvent(new CustomEvent('fs:auth:expired', { detail: { status: 401 } }));
          window.dispatchEvent(new CustomEvent('fs:logout'));
        }
        return res;
      };
    }
  } catch(e) { console.error('fs_compat init error', e); }

  // migration helper: move fs_cart -> fs_cart_<userId> if userId exists
  window.fsCartMigration = function(){
    try {
      const userId = window.getCurrentUserId ? window.getCurrentUserId() : (localStorage.getItem('fs_user_id') || null);
      const globalKey = 'fs_cart';
      const guestKey = 'fs_cart_guest';
      if (localStorage.getItem(globalKey)) {
        const data = localStorage.getItem(globalKey);
        if (userId) {
          localStorage.setItem(`fs_cart_${userId}`, data);
        } else {
          localStorage.setItem(guestKey, data);
        }
        localStorage.removeItem(globalKey);
        return true;
      }
    } catch(e){}
    return false;
  };

  // run migration once
  try { window.fsCartMigration(); } catch(e){}
})();
